(function(root){
'use strict';
const enabled=()=>root.VaultCommercialConfig?.mode==='account'&&location.protocol==='chrome-extension:';
async function command(action,data={}){const r=await chrome.runtime.sendMessage({type:'vault-account',action,...data});if(!r?.ok)throw Error(r?.error||'Accounts are unavailable.');return r.result;}
const node=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
function modal(){const focus=document.activeElement,d=node('dialog'),title=node('h2','Your Vault account'),close=node('button','Close');d.className='research-dialog account-dialog';title.id='account-title';d.setAttribute('aria-labelledby',title.id);close.type='button';close.onclick=()=>d.close();const head=node('div');head.className='research-heading';head.append(title,close);const body=node('div'),error=node('p');error.setAttribute('role','alert');d.append(head,error,body);document.body.append(d);d.addEventListener('close',()=>{d.remove();if(focus?.isConnected)focus.focus();},{once:true});d.showModal();return {d,body,error};}
async function open(){const {d,body,error}=modal();let busy=false,emailValue='';const work=fn=>async()=>{if(busy)return;busy=true;error.textContent='';body.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();}catch(e){error.textContent=e.message;}finally{busy=false;body.querySelectorAll('button').forEach(b=>b.disabled=false);}};
 function button(text,fn){const b=node('button',text);b.type='button';b.onclick=work(fn);return b;}
 function field(label,type){const l=node('label',label),i=node('input');i.type=type;l.append(i);body.append(l);return i;}
 async function render(){body.replaceChildren();const s=await command('status');if(!s.signedIn){body.append(node('p','Sign in to get 50 successful automatic runs. Your research stays in this browser.'));const email=field('Email','email');email.autocomplete='email';email.required=true;email.value=emailValue;body.append(button('Send sign-in code',async()=>{if(!email.reportValidity())return;emailValue=email.value.trim();await command('send-code',{email:emailValue});code();}));email.focus();return;}
 body.append(node('p',s.email),node('h3',s.pro?'Pro · ₹899/month':'Community · '+s.remaining+' free runs available'),node('p',s.pro?'Automatic runs and all Pro research tools are available.':s.used+' of 50 successful free runs used.'),node('p','Saved results, comparisons, backups and exports remain available.'));if(s.reserved)body.append(node('p',s.reserved+' unfinished '+(s.reserved===1?'test holds a slot':'tests hold slots')+'. Review unfinished tests in My studies.'));
 if(s.paidUntil)body.append(node('p','Paid access through '+new Date(s.paidUntil).toLocaleDateString('en-IN')));
 if(s.reserved)body.append(button('Recover unfinished runs',async()=>{const pending=await command('pending');const list=node('div');list.append(node('p','Use this only if the study is missing after reinstalling. First stop tests on all other devices. Studies still in this library must be reviewed in My studies.'));for(const r of pending){const item=node('div');item.append(node('span','Run '+r.runId+' · '+new Date(r.createdAt).toLocaleString('en-IN')),button('Release this unfinished slot',async()=>{if(!confirm('Confirm this run is no longer active on any device and no saved result can be recovered. Release its unfinished slot?'))return;await command('recover-run',{runId:r.runId});await render();}));list.append(item);}body.append(list);}));
 if(!s.pro)body.append(button('Upgrade to Pro · ₹899/month',async()=>{const r=await command('upgrade');const url=new URL(r.url);if(url.protocol!=='https:'||!['rzp.io','razorpay.com'].includes(url.hostname))throw Error('Invalid payment link.');await chrome.tabs.create({url:url.href});body.append(node('p','Complete payment in the new tab, then refresh your account status here.'));}));
 if(s.pro&&s.subscriptionStatus==='active')body.append(button('Cancel renewal',async()=>{if(!confirm('Cancel future renewals? Your paid access continues through the current billing period.'))return;await command('cancel');await render();}));
 body.append(button('Refresh account status',async()=>{await command('refresh-billing');await render();}),button('Sign out',async()=>{await command('sign-out');await render();}));await badge();}
 function code(){body.replaceChildren(node('p','Enter the code sent to '+emailValue+'.'));const token=field('Email code','text');token.inputMode='numeric';token.autocomplete='one-time-code';token.maxLength=10;body.append(button('Verify and sign in',async()=>{await command('verify-code',{email:emailValue,token:token.value.trim()});await render();}),button('Use another email',render));token.focus();}
 try{await render();}catch(e){error.textContent=e.message;body.append(node('p','You can still open and export your saved work.'));}return d;
}
async function badge(){if(!enabled())return;const b=document.getElementById('vault-plan');try{const s=await command('status');if(b)b.textContent=s.signedIn?(s.pro?'Pro':s.remaining+' free runs'):'Sign in';}catch{if(b)b.textContent='Account';}}
async function requireFeature(feature){if(!enabled())return;try{await command('feature',{feature});}catch(e){await open();throw e;}}
async function start(count){if(!enabled())return;try{return await command('start',{count});}catch(e){await open();throw e;}}
root.VaultAccountUI={enabled,command,open,badge,requireFeature,start};
})(window);
